/**
 * Unit tests for CategoryPlot.getRangeAxisIndex.
 */
public class CategoryPlot_getRangeAxisIndex_TriageGen1Test {

    private CategoryPlot categoryPlot;
    private ValueAxis mockAxis;

    @Before
    public void setUp() {
        categoryPlot = new CategoryPlot();
        mockAxis = mock(ValueAxis.class);
    }

    /**
     * Tests that the method returns the correct index when the axis is found 
     * directly in the CategoryPlot's range axes.
     */
    @Test
    public void testGetRangeAxisIndex_FoundInCurrentPlot() {
        // Arrange
        ValueAxis axis1 = mock(ValueAxis.class);
        ValueAxis axis2 = mock(ValueAxis.class);
        categoryPlot.setRangeAxis(axis1);
        categoryPlot.setRangeAxis(1, axis2);

        // Act
        int index0 = categoryPlot.getRangeAxisIndex(axis1);
        int index1 = categoryPlot.getRangeAxisIndex(axis2);

        // Assert
        assertEquals("Should find axis at index 0", 0, index0);
        assertEquals("Should find axis at index 1", 1, index1);
    }

    /**
     * Tests that the method returns -1 when the axis is not found in the 
     * current plot and the parent is not a CategoryPlot.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInCurrentAndParentIsNotCategoryPlot() {
        // Arrange
        // We simulate a parent that is a generic Plot (not CategoryPlot)
        // Since getParent() is likely protected/internal, we rely on the implementation logic.
        // In JFreeChart, if the plot is not attached to a Chart, getParent() returns null.

        // Act
        int result = categoryPlot.getRangeAxisIndex(mockAxis);

        // Assert
        assertEquals("Should return -1 if not found and no parent", -1, result);
    }

    /**
     * Tests that the method delegates to the parent CategoryPlot 
     * when the axis is not found in the current plot.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInCurrentButFoundInParentCategoryPlot() {
        // Arrange
        CategoryPlot parentPlot = new CategoryPlot();
        ValueAxis parentAxis = mock(ValueAxis.class);
        parentPlot.setRangeAxis(parentAxis);

        // We need to link the plots. In JFreeChart, this is usually done via Chart.
        // However, since we are testing the logic of getRangeAxisIndex, 
        // we assume a scenario where CategoryPlot is nested or the parent is a CategoryPlot.
        // Because we cannot easily mock 'getParent()' if it's a final or internal method, 
        // we use a subclass to inject the parent behavior for testing the branch.

        CategoryPlot childPlot = new CategoryPlot() {
            @Override
            public Plot getParent() {
                return parentPlot;
            }
        };

        // Act
        int result = childPlot.getRangeAxisIndex(parentAxis);

        // Assert
        assertEquals("Should delegate to parent CategoryPlot and return correct index", 0, result);
    }

    /**
     * Tests that the method returns -1 when the axis is not found in the current plot
     * and not found in the parent CategoryPlot.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInCurrentAndNotFoundInParentCategoryPlot() {
        // Arrange
        CategoryPlot parentPlot = new CategoryPlot();
        CategoryPlot childPlot = new CategoryPlot() {
            @Override
            public Plot getParent() {
                return parentPlot;
            }
        };

        // Act
        int result = childPlot.getRangeAxisIndex(mockAxis);

        // Assert
        assertEquals("Should return -1 if not found in child or parent", -1, result);
    }
}
